mapper.select:
SELECT  FROM report_definition
WHERE workspace_id = #{workspaceId}
ORDER BY updated_at DESC, id DESC

mapper.update:
UPDATE report_definition
SET name = #{name}, description = #{description}, cadence = #{cadence},
    template_key = #{templateKey}, config_json = #{configJson}
WHERE workspace_id = #{workspaceId} AND id = #{id}

mapper.select:
SELECT id, report_definition_id, period_start, period_end, generated_by, generated_at
FROM report_snapshot
WHERE workspace_id = #{workspaceId} AND report_definition_id = #{reportDefinitionId}
ORDER BY generated_at DESC, id DESC
LIMIT #{limit}

SELECT  FROM report_snapshot
WHERE workspace_id = #{workspaceId}
  AND report_definition_id = #{reportDefinitionId}
  AND id = #{id}

mapper.delete:
DELETE FROM report_snapshot
WHERE workspace_id = #{workspaceId}
  AND report_definition_id = #{reportDefinitionId}
  AND id = #{id}

choose.otherwise:
CASE

    WHEN  >= #{segment.startUtc}
      AND  < #{segment.endUtc}
    THEN TIMESTAMPADD(MINUTE, #{segment.offsetMinutes}, )

  ELSE 
END

sql.if:
AND EXISTS (
  SELECT 1 FROM deal_tag dt
  JOIN tag filter_tag ON filter_tag.id = dt.tag_id AND filter_tag.workspace_id = #{query.workspaceId}
  WHERE dt.deal_id = d.id AND dt.tag_id IN
  #{id}
)

mapper.select:
SELECT AS group_key, AS group_label, 'count' AS unit, COUNT(*) AS value FROM activity a WHERE a.workspace_id = #{query.workspaceId} AND a.timestamp >= #{query.startUtc} AND a.timestamp < #{query.endUtc}
AND a.created_by_id IN #{id}
AND EXISTS (SELECT 1 FROM deal ad WHERE ad.workspace_id = #{query.workspaceId} AND ad.id = a.deal_id AND ad.pipeline_id IN #{id})
GROUP BY group_key, group_label ORDER BY group_key

SELECT  AS group_key,
        AS group_label,
       'count' AS unit,
       COUNT(*) AS value
FROM task t
WHERE t.workspace_id = #{query.workspaceId}
  AND t.updated_at >= #{query.startUtc} AND t.updated_at < #{query.endUtc}

  AND t.assigned_to_id IN
  #{id}


  AND t.status IN
  #{status}

GROUP BY group_key, group_label
ORDER BY group_key

SELECT p.id
FROM person p
WHERE p.created_at <= #{asOf}
  AND (
    p.workspace_id = #{workspaceId}
    OR EXISTS (
      SELECT 1
      FROM person_share ps
      WHERE ps.person_id = p.id
        AND ps.workspace_id = #{workspaceId}
        AND ps.created_at <= #{asOf}
    )
  )
ORDER BY p.id
